const expected = {
  ownerId: '08e9abae-db9c-46b4-81be-c90bf7ea04e5',
  companyId: '6faa0c8b-733f-4406-91c9-638a4e93ee11',
  companyName: 'Empresa Horizonte Local',
  documentId: '00000000-0000-4000-8000-0000000009e2',
  fileName: 'TESTE_FINANCEIRO_09B_SINTETICO.xlsx',
  sourceEtag: 'synthetic-local-sha256-2a5a4be80c428acf5c14c21bfc214d8020215ddbc95eb1f74c7161493de9e39a',
  sourcePath: '/drive/root:/Deskboard KPIs/Local Synthetic/TESTE_FINANCEIRO_09B_SINTETICO.xlsx',
  fixturePath: '/fixtures/09b-synthetic-financial-report.xlsx',
  fileSize: 12956,
  fixtureSha256: '2a5a4be80c428acf5c14c21bfc214d8020215ddbc95eb1f74c7161493de9e39a',
  periodMonth: '2026-09',
};

// A future authorized operator must validate service health, both n8n credentials
// and local-only routing before changing this explicit gate.
const operationalPreflightApproved = false;

return [{ json: { localOnly: true, operationalPreflightApproved, expected } }];

const response = $input.first().json;
const expected = $('Define local-only contract').first().json.expected;
const statusCode = Number(response.statusCode ?? 200);
const body = response.body ?? response;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!Number.isInteger(statusCode) || statusCode < 200 || statusCode >= 300) {
  return [{ json: { outcome: 'terminal', result: { status: 'failure', stage: 'claim', code: 'claim_request_failed', localOnly: true } } }];
}
if (body?.has_document === false && body?.reason === 'no_eligible_document') {
  return [{ json: { outcome: 'terminal', result: { status: 'skipped', stage: 'claim', code: 'no_eligible_document', localOnly: true } } }];
}
if (body?.has_document !== true) {
  return [{ json: { outcome: 'terminal', result: { status: 'failure', stage: 'claim', code: 'invalid_claim_response', localOnly: true } } }];
}

const identityMatches = body.document_id === expected.documentId
  && body.owner_id === expected.ownerId
  && body.company_id === expected.companyId
  && body.source_etag === expected.sourceEtag
  && body.file_name === expected.fileName
  && body.file_size === expected.fileSize
  && body.extension === 'xlsx'
  && uuid.test(String(body.claim_id ?? ''))
  && typeof body.external_drive_id === 'string'
  && body.external_drive_id.length > 0
  && typeof body.external_file_id === 'string'
  && body.external_file_id.length > 0;
const pathContractMatches = expected.sourcePath.startsWith('/drive/root:/Deskboard KPIs/')
  && expected.sourcePath.endsWith(`/${expected.fileName}`);

if (!identityMatches || !pathContractMatches) {
  return [{ json: { outcome: 'terminal', result: { status: 'failure', stage: 'claim', code: 'claimed_document_identity_mismatch', localOnly: true } } }];
}

return [{ json: { outcome: 'claimed', expected, claim: body, pathEligibilityValidatedByClaimRpc: true } }];

const item = $input.first();
const expected = item.json.expected;
const claim = item.json.claim;
if (item.json.pathEligibilityValidatedByClaimRpc !== true
  || expected.fixturePath !== '/fixtures/09b-synthetic-financial-report.xlsx'
  || expected.fixtureSha256 !== '2a5a4be80c428acf5c14c21bfc214d8020215ddbc95eb1f74c7161493de9e39a'
  || expected.fileSize !== 12956
  || claim.document_id !== expected.documentId
  || claim.company_id !== expected.companyId
  || claim.source_etag !== expected.sourceEtag
  || !item.binary?.data) {
  throw new Error('synthetic_fixture_not_eligible');
}
return [item];

const response = $input.first().json;
const context = $('Validate approved fixture').first().json;
const expected = context.expected;
const claim = context.claim;
const statusCode = Number(response.statusCode ?? 200);
const extraction = response.body ?? response;
const supported = new Set(['revenue', 'expense', 'net_result', 'cash_available']);
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const terminal = (code) => [{ json: { outcome: 'terminal', result: { status: 'failure', stage: 'extraction', code, localOnly: true, documentId: expected.documentId } } }];

try {
  if (!Number.isInteger(statusCode) || statusCode < 200 || statusCode >= 300) return terminal('worker_request_failed');
  if (extraction?.schemaVersion !== 'financial-extraction.v1' || extraction?.status !== 'needs_review' || extraction?.publishable !== false) throw new Error('invalid_extraction_contract');
  if (extraction.metadata?.company?.id !== expected.companyId || extraction.metadata?.company?.name !== expected.companyName || extraction.metadata?.document?.id !== expected.documentId || extraction.metadata?.document?.etag !== expected.sourceEtag || extraction.metadata?.document?.fileName !== expected.fileName || extraction.metadata?.periodMonth !== expected.periodMonth) throw new Error('extraction_identity_mismatch');
  if (!Array.isArray(extraction.facts) || !Array.isArray(extraction.bankTransactions)) throw new Error('invalid_extraction_payload');

  const keys = new Set();
  const rows = [];
  let deferredFactCount = 0;
  for (const fact of extraction.facts) {
    if (typeof fact?.logicalKey !== 'string' || !fact.logicalKey || keys.has(fact.logicalKey)) throw new Error('invalid_or_duplicate_logical_key');
    keys.add(fact.logicalKey);
    if (fact.companyId !== expected.companyId || fact.companyName !== expected.companyName || fact.documentId !== expected.documentId || fact.sourceEtag !== expected.sourceEtag) throw new Error('fact_identity_mismatch');

    const canonical = fact.includedInConsolidatedKpi === true && fact.aggregationLevel === 'canonical';
    if (!canonical) { deferredFactCount += 1; continue; }
    if (!supported.has(fact.metricCode)) throw new Error('unsupported_canonical_fact');
    if (fact.periodMonth !== expected.periodMonth || fact.currency !== 'BRL' || fact.reviewStatus !== 'needs_review' || fact.sourceScope !== 'business') throw new Error('invalid_canonical_fact');
    if (!/^-?\d+\.\d{2}$/.test(fact.amount) || !/^-?\d+$/.test(fact.amountMinor)) throw new Error('invalid_financial_amount');
    const amountMatch = fact.amount.match(/^(-?)(\d+)\.(\d{2})$/);
    const calculatedMinor = ((amountMatch[1] === '-' ? -1n : 1n) * (BigInt(amountMatch[2]) * 100n + BigInt(amountMatch[3]))).toString();
    if (BigInt(fact.amountMinor).toString() !== calculatedMinor || (fact.metricCode !== 'net_result' && fact.amount.startsWith('-'))) throw new Error('invalid_financial_sign');
    const sheet = String(fact.evidence?.sheet ?? '').trim();
    const sourceCell = String(fact.evidence?.cellAddress ?? '');
    const rowMatch = sourceCell.match(/(\d+)$/);
    const sourceRow = rowMatch ? Number(rowMatch[1]) : 0;
    if (!sheet || sheet.length > 120 || /[\u0000-\u001f\u007f]/.test(sheet) || !/^[A-Z]{1,3}[1-9][0-9]*$/.test(sourceCell) || !Number.isSafeInteger(sourceRow) || sourceRow <= 0) throw new Error('invalid_fact_provenance');
    const logicalKey = [expected.documentId, expected.sourceEtag, sheet, sourceCell, fact.metricCode, fact.periodMonth].join(':');
    if (fact.logicalKey !== logicalKey) throw new Error('logical_key_mismatch');
    rows.push({ logical_key: logicalKey, company_id: expected.companyId, company_name: expected.companyName, month: `${fact.periodMonth}-01`, metric_code: fact.metricCode, amount: fact.amount, currency: 'BRL', sheet, source_row: sourceRow, source_cell: sourceCell, review_status: 'needs_review' });
  }

  const available = new Set(rows.map((row) => row.metric_code));
  if ([...supported].some((metric) => !available.has(metric))) throw new Error('missing_required_canonical_fact');
  if (!uuid.test(String(claim.claim_id ?? ''))) throw new Error('invalid_claim_id');

  return [{ json: { outcome: 'ready', supportedFactCount: rows.length, deferredFactCount, deferredBankTransactionCount: extraction.bankTransactions.length, rpcPayload: { p_document_id: expected.documentId, p_claim_id: claim.claim_id, p_source_etag: expected.sourceEtag, p_status: 'needs_review', p_rows: rows, p_note: `financial-extraction.v1 canonical facts; deferred_facts=${deferredFactCount}; deferred_bank_transactions=${extraction.bankTransactions.length}`, p_excerpt: null } } }];
} catch (error) {
  return terminal(error instanceof Error ? error.message : 'invalid_extraction_contract');
}

const response = $input.first().json;
const context = $('Validate extraction and build v2 payload').first().json;
const expected = $('Define local-only contract').first().json.expected;
const statusCode = Number(response.statusCode ?? 200);
const body = response.body ?? response;

if (!Number.isInteger(statusCode) || statusCode < 200 || statusCode >= 300) {
  return [{ json: { status: 'failure', stage: 'persistence', code: 'completion_request_failed', localOnly: true, documentId: expected.documentId } }];
}
const insertedRows = Number(body?.inserted_rows);
const unchangedRows = Number(body?.unchanged_rows);
const valid = body?.success === true
  && body?.contract_version === 2
  && body?.document_id === expected.documentId
  && body?.status === 'needs_review'
  && body?.requires_approval === true
  && Number.isSafeInteger(insertedRows)
  && insertedRows >= 0
  && Number.isSafeInteger(unchangedRows)
  && unchangedRows >= 0
  && insertedRows + unchangedRows === context.supportedFactCount;
if (!valid) {
  return [{ json: { status: 'failure', stage: 'persistence', code: 'invalid_completion_response', localOnly: true, documentId: expected.documentId } }];
}
return [{ json: { status: 'success', stage: 'persistence', contractVersion: 2, localOnly: true, documentId: expected.documentId, reviewStatus: 'needs_review', publishable: false, insertedRows, unchangedRows, deferredFactCount: context.deferredFactCount, deferredBankTransactionCount: context.deferredBankTransactionCount } }];
